/** Native final-skull clicks, natural shield/cooldown ticks and actual client finishing attacks. */
public final class GraphicalWitherPatchAudit {
    private static final BlockPos CENTER=new BlockPos(416,4,64);
    private final String viewer=FabricLoader.getInstance().isModLoaded("roughlyenoughitems")?"rei":FabricLoader.getInstance().isModLoaded("jei")?"jei":"plain";
    private final List<Map<String,Object>> scenes=new ArrayList<>(),screenshots=new ArrayList<>();
    private UUID playerId;
    private Scene scene;
    private Sample sample;
    private CompletableFuture<?> pending;
    private int phase,phaseTicks,ticks,stable,attackPackets;
    private boolean started,complete,restoring,survival;
    private Perspective oldPerspective;
    private int oldFov;
    private record Sample(int bossId,int invulnerability,float health,float maximum,int minions,List<Integer> ids,List<Float> hp,List<Double> y,boolean creativeTargeted,long elapsed,long afterShield,int normalStars,int specialStars,int bookCount,int xp,boolean dead,boolean cleaned){}
    public void start(MinecraftClient client){require(!started&&client.player!=null&&client.getServer()!=null,"Wither proof needs an integrated graphical player");started=true;playerId=client.player.getUuid();oldPerspective=client.options.getPerspective();oldFov=client.options.getFov().getValue();client.setScreen(null);client.options.useKey.setPressed(false);client.options.attackKey.setPressed(false);client.options.setPerspective(Perspective.FIRST_PERSON);client.options.getFov().setValue(70);pending=server(client,p->{scene=new Scene(p);scene.prepare(false);return null;});}
    public boolean tick(MinecraftClient client){try{return tickInternal(client);}catch(RuntimeException|Error failure){restore(client);throw failure;}}
    private boolean tickInternal(MinecraftClient client){require(started,"Wither proof not started");if(complete)return true;require(++ticks<3500,"Wither graphical proof timeout phase="+phase+" survival="+survival+" sample="+sample);phaseTicks++;if(pending!=null&&pending.isCompletedExceptionally())pending.join();switch(phase){
        case 0->{if(done()){pending.join();pending=null;next(1);}}
        case 1->{require(phaseTicks<300,"Final-skull fixture failed to synchronize camera or inventory");client.player.getInventory().selectedSlot=0;if(!readyAt(client,scene.camera,scene.ritualCenter)||!client.player.getMainHandStack().isOf(Items.WITHER_SKELETON_SKULL)||phaseTicks<25)return false;if(++stable<10)return false;shot(client,"ritual-before");require(client.interactionManager.interactBlock(client.player,Hand.MAIN_HAND,(BlockHitResult)client.crosshairTarget).isAccepted(),"Actual final-skull block interaction was rejected");client.player.swingHand(Hand.MAIN_HAND);next(2);}
        case 2->{if(pending==null&&phaseTicks>=15)pending=server(client,p->{scene.findRitualBoss();scene.observe();return scene.sample();});if(!done())return false;sample=(Sample)pending.join();pending=null;require(sample.maximum()==650&&sample.invulnerability()>0,"Native guaranteed ritual did not create a650HPprotected special Wither");next(3);}
        case 3->{require(phaseTicks<800,"Native Wither failed its first visible wave: "+sample);if(client.player.squaredDistanceTo(scene.camera)>.06)return false;look(client,Vec3d.ofCenter(CENTER).add(0,1,0));if(pending==null&&phaseTicks%5==0)pending=server(client,p->scene.sample());if(done()){sample=(Sample)pending.join();pending=null;if(sample.minions()==2){require(sample.afterShield()>=190&&sample.afterShield()<=315,"First wave outside native10-15second post-shield window: "+sample);require(sample.hp().stream().allMatch(h->h==20),"Visible wave did not have20HPminions");require(!sample.creativeTargeted(),"Minions targeted the Creative observer");if(survival)require(sample.y().stream().allMatch(y->y<CENTER.getY()+6),"Flying boss hid Survival minions above the arena roof");next(4);}}}
        case 4->{require(phaseTicks<200,"Actual client did not receive both minion entities");if(sample.ids().stream().anyMatch(id->client.world.getEntityById(id)==null))return false;var visible=sample.ids().stream().map(client.world::getEntityById).min(Comparator.comparingDouble(client.player::squaredDistanceTo)).orElseThrow();look(client,visible.getBoundingBox().getCenter());if(phaseTicks<25)return false;shot(client,"native-first-wave");scenes.add(Map.of("Mode",survival?"Survival":"Creative","NativeRitual",true,"BossMaximum",sample.maximum(),"FirstWaveAfterShieldTicks",sample.afterShield(),"Minions",sample.minions(),"MinionMaximumHealth",sample.hp(),"MinionY",sample.y(),"CreativeTargeted",sample.creativeTargeted()));pending=server(client,p->{scene.prepareFinish();return scene.sample();});next(5);}
        case 5->{if(pending!=null){if(!done())return false;sample=(Sample)pending.join();pending=null;}require(phaseTicks<200,"Actual client finishing camera/weapon did not synchronize");if(client.player.squaredDistanceTo(scene.camera)>.06||!client.player.getMainHandStack().isOf(Items.NETHERITE_SWORD)||phaseTicks<25)return false;var entity=client.world.getEntityById(sample.bossId());require(entity instanceof WitherEntity,"Client lost native Wither before finishing hit");look(client,entity.getBoundingBox().getCenter());shot(client,"native-finishing-hit");client.interactionManager.attackEntity(client.player,entity);client.player.swingHand(Hand.MAIN_HAND);attackPackets++;next(6);}
        case 6->{require(phaseTicks<150,"Actual Wither finishing hit did not yield expected native loot: "+sample);if(pending==null&&phaseTicks%5==0)pending=server(client,p->scene.sample());if(done()){sample=(Sample)pending.join();pending=null;if(sample.dead()){require(sample.normalStars()==0&&sample.specialStars()==1&&sample.bookCount()==1&&sample.xp()==50&&sample.cleaned(),"Native variant death star/book/XP/cleanup mismatch: "+sample);shot(client,"native-special-star-only");scenes.add(Map.of("Mode",survival?"Survival":"Creative","OrdinaryStarDrops",sample.normalStars(),"SpecialStarDrops",sample.specialStars(),"EnchantedBooks",sample.bookCount(),"NativeExperience",sample.xp(),"MinionsRemovedOnBossDeath",sample.cleaned()));if(!survival){survival=true;pending=server(client,p->{scene.prepare(true);return null;});next(0);}else{restore(client);next(7);}}}}
        case 7->{if(pending!=null){if(!done())return false;pending.join();pending=null;}if(scene.restored&&phaseTicks>=25){write(client);complete=true;return true;}}
        default->throw new IllegalStateException("Unknown Wither graphical phase "+phase);
    }return false;}
    private static boolean readyAt(MinecraftClient client,Vec3d position,BlockPos target){if(client.player.squaredDistanceTo(position)>.06)return false;look(client,Vec3d.ofCenter(target).add(0,.5,0));return client.crosshairTarget instanceof BlockHitResult hit&&hit.getBlockPos().equals(target);}
    private static void look(MinecraftClient client,Vec3d target){var d=target.subtract(client.player.getEyePos());client.player.setYaw((float)(Math.toDegrees(Math.atan2(d.z,d.x))-90));client.player.setPitch((float)-Math.toDegrees(Math.atan2(d.y,Math.hypot(d.x,d.z))));}
    private boolean done(){return pending!=null&&pending.isDone();}
    private void next(int value){phase=value;phaseTicks=0;stable=0;}
    private void shot(MinecraftClient client,String view){String name="rust-and-ruin-"+viewer+"-wither-patch-"+(survival?"survival-":"creative-")+view+".png";ScreenshotRecorder.saveScreenshot(client.runDirectory,name,client.getFramebuffer(),text->{});screenshots.add(Map.of("Mode",survival?"Survival":"Creative","View",view,"Screenshot",name));org.slf4j.LoggerFactory.getLogger("tetanusmod").info("GRAPHICAL_WITHER_PATCH_VIEW {} {}",survival?"survival":"creative",view);}
    private <T> CompletableFuture<T> server(MinecraftClient client,Function<ServerPlayerEntity,T> action){var future=new CompletableFuture<T>();client.getServer().execute(()->{try{var p=client.getServer().getPlayerManager().getPlayer(playerId);require(p!=null,"Wither graphical actor disconnected");future.complete(action.apply(p));}catch(Throwable failure){future.completeExceptionally(failure);}});return future;}
    private void restore(MinecraftClient client){if(restoring)return;restoring=true;client.options.useKey.setPressed(false);client.options.attackKey.setPressed(false);client.setScreen(null);client.options.setPerspective(oldPerspective);client.options.getFov().setValue(oldFov);if(scene!=null&&client.getServer()!=null)pending=server(client,p->{scene.restore();return null;});else pending=CompletableFuture.completedFuture(null);}
    private void write(MinecraftClient client){var report=new LinkedHashMap<String,Object>();report.put("Result","PASS");report.put("ActualGraphicalClient",true);report.put("ActualFinalSkullPlacementPackets",2);report.put("ActualClientAttackPackets",attackPackets);report.put("DirectSpawnWaveCalls",0);report.put("DirectEncounterTickCalls",0);report.put("SpawnCooldownWrites",0);report.put("ActualNativeWorldScheduling",true);report.put("Fixture","Disposable bedrock arena; guaranteed native netherite-enhanced ritual. Survival uses synchronized camera flight/invulnerability. Boss health reduced to1 only after native650HPand timed20HPminion proof, then actual client finishing hit. This is a functionality proof, not a full balance playthrough.");report.put("NativeExperienceAccounting","Remaining native orb Value*Count plus actual player total-experience gain; tolerates legitimate early pickup");report.put("OriginalPlayerAndRulesRestored",scene.restored);report.put("Scenes",scenes);report.put("Screenshots",screenshots);try{Files.writeString(client.runDirectory.toPath().resolve("graphical-wither-patch-"+viewer+".json"),new GsonBuilder().setPrettyPrinting().create().toJson(report));}catch(Exception failure){throw new IllegalStateException("Cannot write Wither graphical proof",failure);}}
    private static void require(boolean value,String message){if(!value)throw new IllegalStateException(message);}
    private static final class Scene {
        final ServerPlayerEntity player;final ServerWorld world;final Vec3d oldPosition;final float oldYaw,oldPitch,oldHealth;final GameMode oldMode;final boolean oldGravity,oldFlying,oldAllowFlying,oldInvulnerable,oldGriefing,oldSpawning,oldLoot;final NbtList inventory;final NbtCompound hunger=new NbtCompound();final List<StatusEffectInstance> effects;final int selected,oldLevel,oldTotal;final float oldProgress;final Map<BlockPos,BlockState> blocks=new LinkedHashMap<>();
        Vec3d camera;BlockPos ritualCenter;WitherEntity boss;long started,shieldEnded=-1;int xpBaseline;boolean restored;
        Scene(ServerPlayerEntity p){player=p;world=p.getServerWorld();require(world.getChunkManager().getChunkGenerator() instanceof net.minecraft.world.gen.chunk.FlatChunkGenerator,"Wither proof requires a fresh disposable flat test world");oldPosition=p.getPos();oldYaw=p.getYaw();oldPitch=p.getPitch();oldHealth=p.getHealth();oldMode=p.interactionManager.getGameMode();oldGravity=p.hasNoGravity();oldFlying=p.getAbilities().flying;oldAllowFlying=p.getAbilities().allowFlying;oldInvulnerable=p.getAbilities().invulnerable;inventory=p.getInventory().writeNbt(new NbtList());selected=p.getInventory().selectedSlot;oldLevel=p.experienceLevel;oldTotal=p.totalExperience;oldProgress=p.experienceProgress;p.getHungerManager().writeNbt(hunger);effects=p.getStatusEffects().stream().map(StatusEffectInstance::new).toList();oldGriefing=world.getGameRules().getBoolean(GameRules.DO_MOB_GRIEFING);oldSpawning=world.getGameRules().getBoolean(GameRules.DO_MOB_SPAWNING);oldLoot=world.getGameRules().getBoolean(GameRules.DO_MOB_LOOT);for(int x=-12;x<=12;x++)for(int z=-12;z<=12;z++)for(int y=-1;y<=16;y++){var at=CENTER.add(x,y,z);require(world.getBlockEntity(at)==null,"Wither fixture refuses an existing block entity at "+at);blocks.put(at,world.getBlockState(at));}}
        void flight(){player.setNoGravity(true);player.getAbilities().allowFlying=true;player.getAbilities().flying=true;player.getAbilities().invulnerable=true;player.sendAbilitiesUpdate();player.setVelocity(Vec3d.ZERO);}
        void clearEntities(){if(boss!=null){WitherBossEncounter.bossDied(boss);boss.discard();boss=null;}for(var e:world.getOtherEntities(null,new Box(CENTER).expand(20),e->e instanceof ItemEntity||e instanceof ExperienceOrbEntity||e instanceof WitherMinionEntity||e instanceof net.minecraft.entity.projectile.WitherSkullEntity))e.discard();}
        void prepare(boolean survival){player.closeHandledScreen();clearEntities();shieldEnded=-1;world.getGameRules().get(GameRules.DO_MOB_GRIEFING).set(false,world.getServer());world.getGameRules().get(GameRules.DO_MOB_SPAWNING).set(false,world.getServer());world.getGameRules().get(GameRules.DO_MOB_LOOT).set(true,world.getServer());for(var at:blocks.keySet())world.setBlockState(at,at.getY()==CENTER.getY()-1?Blocks.BEDROCK.getDefaultState():Blocks.AIR.getDefaultState());if(survival)for(int x=-11;x<=11;x++)for(int z=-11;z<=11;z++)world.setBlockState(CENTER.add(x,6,z),Blocks.BEDROCK.getDefaultState());
            player.changeGameMode(survival?GameMode.SURVIVAL:GameMode.CREATIVE);flight();player.clearStatusEffects();player.addStatusEffect(new StatusEffectInstance(StatusEffects.NIGHT_VISION,5000,0,false,false,false));player.getInventory().clear();player.getInventory().selectedSlot=0;player.getInventory().setStack(0,new ItemStack(Items.WITHER_SKELETON_SKULL));ritualCenter=CENTER.up(survival?11:1);world.setBlockState(ritualCenter,Blocks.NETHERITE_BLOCK.getDefaultState());for(var at:List.of(ritualCenter.down(),ritualCenter.east(),ritualCenter.west()))world.setBlockState(at,ModBlocks.TETANIZED_SOUL_SAND.getDefaultState());world.setBlockState(ritualCenter.up().east(),Blocks.WITHER_SKELETON_SKULL.getDefaultState());world.setBlockState(ritualCenter.up().west(),Blocks.WITHER_SKELETON_SKULL.getDefaultState());camera=Vec3d.ofBottomCenter(ritualCenter.up()).add(0,.2,3);player.teleport(world,camera.x,camera.y,camera.z,180,25);player.currentScreenHandler.sendContentUpdates();started=world.getTime();}
        void findRitualBoss(){var found=world.getEntitiesByClass(WitherEntity.class,new Box(ritualCenter).expand(5),e->MobVariants.permanent(e));require(found.size()==1,"Actual final skull did not invoke the guaranteed native special ritual");boss=found.get(0);require(boss.getInvulnerableTimer()>0&&boss.getMaxHealth()==650,"Native ritual did not retain its charging phase and650HP");}
        void observe(){flight();camera=Vec3d.ofBottomCenter(CENTER).add(0,2,10);player.teleport(world,camera.x,camera.y,camera.z,180,10);player.setVelocity(Vec3d.ZERO);}
        Sample sample(){require(boss!=null,"No native ritual boss to inspect");if(shieldEnded<0&&boss.getInvulnerableTimer()==0)shieldEnded=world.getTime();var state=(WitherBossState)boss;var minions=new ArrayList<WitherMinionEntity>();for(var id:state.rustruin$minionLeases().keySet())if(world.getEntity(id) instanceof WitherMinionEntity m&&m.isAlive())minions.add(m);int normal=player.getInventory().count(Items.NETHER_STAR),special=player.getInventory().count(ModItems.TETANIZED_WITHER_STAR),books=0,xp=player.totalExperience-xpBaseline;for(var stack:player.getInventory().main)if(EnchantmentHelper.get(stack).getOrDefault(ModItems.TETANUS_ENCHANTMENT,0)>0&&stack.isOf(Items.ENCHANTED_BOOK))books+=stack.getCount();for(var item:world.getEntitiesByClass(ItemEntity.class,new Box(CENTER).expand(20),e->true)){var stack=item.getStack();if(stack.isOf(Items.NETHER_STAR))normal+=stack.getCount();if(stack.isOf(ModItems.TETANIZED_WITHER_STAR))special+=stack.getCount();if(stack.isOf(Items.ENCHANTED_BOOK)&&EnchantmentHelper.get(stack).getOrDefault(ModItems.TETANUS_ENCHANTMENT,0)>0)books+=stack.getCount();}for(var orb:world.getEntitiesByClass(ExperienceOrbEntity.class,new Box(CENTER).expand(20),e->true)){var nbt=orb.writeNbt(new NbtCompound());xp+=nbt.getShort("Value")*Math.max(1,nbt.getInt("Count"));}boolean cleaned=state.rustruin$minionLeases().isEmpty()&&world.getEntitiesByClass(WitherMinionEntity.class,new Box(CENTER).expand(20),m->boss.getUuid().equals(m.bossUuid())).isEmpty();return new Sample(boss.getId(),boss.getInvulnerableTimer(),boss.getHealth(),boss.getMaxHealth(),minions.size(),minions.stream().map(Entity::getId).toList(),minions.stream().map(LivingEntity::getMaxHealth).toList(),minions.stream().map(Entity::getY).toList(),minions.stream().anyMatch(m->m.getTarget() instanceof net.minecraft.entity.player.PlayerEntity p&&p.isCreative()),world.getTime()-started,shieldEnded<0?-1:world.getTime()-shieldEnded,normal,special,books,xp,boss.getHealth()<=0,cleaned);}
        void prepareFinish(){require(boss!=null&&boss.getInvulnerableTimer()==0,"Finisher attempted while native spawn protection was active");flight();boss.setAiDisabled(true);boss.setNoGravity(true);boss.setHealth(1);camera=boss.getPos().add(0,.2,3.2);player.teleport(world,camera.x,camera.y,camera.z,180,0);player.getInventory().clear();player.getInventory().setStack(0,new ItemStack(Items.NETHERITE_SWORD));player.getInventory().selectedSlot=0;player.currentScreenHandler.sendContentUpdates();xpBaseline=player.totalExperience;}
        void restore(){if(restored)return;player.closeHandledScreen();clearEntities();for(var entry:blocks.entrySet())world.setBlockState(entry.getKey(),entry.getValue());world.getGameRules().get(GameRules.DO_MOB_GRIEFING).set(oldGriefing,world.getServer());world.getGameRules().get(GameRules.DO_MOB_SPAWNING).set(oldSpawning,world.getServer());world.getGameRules().get(GameRules.DO_MOB_LOOT).set(oldLoot,world.getServer());player.teleport(world,oldPosition.x,oldPosition.y,oldPosition.z,oldYaw,oldPitch);player.changeGameMode(oldMode);player.setNoGravity(oldGravity);player.getAbilities().allowFlying=oldAllowFlying;player.getAbilities().flying=oldFlying;player.getAbilities().invulnerable=oldInvulnerable;player.sendAbilitiesUpdate();player.getInventory().readNbt(inventory.copy());player.getInventory().selectedSlot=selected;player.getHungerManager().readNbt(hunger.copy());player.clearStatusEffects();for(var effect:effects)player.addStatusEffect(new StatusEffectInstance(effect));player.setHealth(oldHealth);player.setExperienceLevel(oldLevel);player.setExperiencePoints(Math.round(oldProgress*player.getNextLevelExperience()));player.totalExperience=oldTotal;player.currentScreenHandler.sendContentUpdates();restored=true;}
    }
}